def min_seconds_to_eat_candies(n, s, k, r, c):
    INF = 10000000000.0
    max_n = 50
    max_k = 2000

    s -= 1  # Convert to 0-based index
    buf = [''] * (max_n + 1)
    dp = [[0 for _ in range(max_n + 1)] for _ in range(max_k + 1)]
    answer = INF

    for i in range(len(c)):
        buf[i] = c[i]

    for i in range(k, -1, -1):
        for j in range(n):
            dp[i][j] = INF

    for j in range(n):
        value = abs(j - s)
        if k - r[j] <= 0:
            answer = min(answer, value)
        else:
            dp[k - r[j]][j] = value

    for i in range(k, 0, -1):
        for j in range(n):
            if dp[i][j] < INF:
                for l in range(n):
                    if buf[j] != buf[l] and r[j] < r[l]:
                        value = dp[i][j] + abs(j - l)
                        if i - r[l] <= 0:
                            answer = min(answer, value)
                        else:
                            dp[i - r[l]][l] = min(dp[i - r[l]][l], value)

    return -1 if answer == INF else answer

def calculate_minimum_years(n: str) -> int:
    def sub(maxs, mins):
        for i in range(len(maxs)):
            if maxs[i] != mins[i]:
                if i == len(maxs) - 1:
                    return int(maxs[i]) - int(mins[i])
                if i == len(maxs) - 2:
                    return int(maxs[i:i + 2]) - int(mins[i:i + 2])
                return 10
        return 0

    def checkEqual(S):
        ans = 8
        for k in range(1, len(S)):
            if len(S) % k != 0:
                continue
            mins = maxs = S[0:k]
            for s in range(0, len(S), k):
                maxs = max(maxs, S[s:s + k])
                mins = min(mins, S[s:s + k])
            ans = min(ans, sub(maxs, mins))
        return ans

    def check12(S):
        maxv = 0
        minv = 10
        p = 0
        while p < len(S):
            v = int(S[p])
            if S[p] == '1' and p + 1 < len(S):
                v = 10 + int(S[p + 1])
                p += 1
            maxv = max(maxv, v)
            minv = min(minv, v)
            p += 1
        return maxv - minv

    return min(checkEqual(n), check12(n))

def maximize_deck_order(deck_size, deck_cards):
    new_deck = []
    used = [0 for _ in range(deck_size)]
    last_used_index = deck_size - 1
    prev_ind = deck_size

    for i in range(deck_size - 1, -1, -1):
        if deck_cards[i] == last_used_index + 1:
            new_deck += deck_cards[i:prev_ind]
            for j in range(i, prev_ind):
                used[deck_cards[j] - 1] = 1
            prev_ind = i
            j = -1
            while True:
                cur_ind = j + last_used_index
                if cur_ind < 0:
                    last_used_index = -1
                    break
                if used[cur_ind]:
                    j -= 1
                    continue
                else:
                    last_used_index = cur_ind
                    break

    return new_deck

