def paintfuck_interpreter(code: str, iterations: int, width: int, height: int) -> str:
    # Filter out non-command characters
    code = ''.join(c for c in code if c in '[news]*')

    # Initialize the data grid with all zeros
    canvas = [[0] * width for _ in range(height)]

    # Initialize pointer position and counters
    row, col = 0, 0
    step, count, loop = 0, 0, 0

    # Execute the code
    while step < len(code) and count < iterations:
        command = code[step]

        if loop:
            if command == '[':
                loop += 1
            elif command == ']':
                loop -= 1
        else:
            if command == 'n':
                row = (row - 1) % height
            elif command == 's':
                row = (row + 1) % height
            elif command == 'w':
                col = (col - 1) % width
            elif command == 'e':
                col = (col + 1) % width
            elif command == '*':
                canvas[row][col] ^= 1
            elif command == '[' and canvas[row][col] == 0:
                loop += 1
            elif command == ']' and canvas[row][col] != 0:
                loop -= 1

        # Move the step pointer and update the iteration count
        step += 1 if not loop else loop // abs(loop)
        count += 1 if not loop else 0

    # Convert the final state of the canvas to the required string format
    return '\r\n'.join(''.join(map(str, row)) for row in canvas)

