def find_permutation(n, a, b):
    if not (-2 < a - b < 2 and a + b < n - 1):
        return -1

    r = list(range(1, n + 1))
    j = a >= b
    k = a > b

    for i in range(2 - j, a + b - k + j, 2):
        r[i:i + 2] = [r[i + 1], r[i]]

    return tuple(r)

def find_min_replacement_length(gene, n=None):
    if n is None:
        n = len(gene)

    # Ensure n is divisible by 4
    if n % 4 != 0:
        raise ValueError("The length of the gene must be divisible by 4.")

    # Count the occurrences of each character in the gene
    count = {}
    for c in gene:
        count[c] = count.get(c, 0) + 1

    # Calculate the required number of each character to make the gene steady
    for c in count:
        if count[c] > n // 4:
            count[c] = count[c] - n // 4
        else:
            count[c] = 0

    # If the gene is already steady, return 0
    if sum((count[c] for c in count)) == 0:
        return 0

    # Initialize variables for the sliding window approach
    count2 = {}
    i, j, best = 0, 0, n

    # Use a sliding window to find the smallest substring that can be replaced
    while j < n:
        while j < n and any((count2.get(c, 0) < count[c] for c in count)):
            count2[gene[j]] = count2.get(gene[j], 0) + 1
            j += 1
        while all((count2.get(c, 0) >= count[c] for c in count)):
            count2[gene[i]] = count2.get(gene[i], 0) - 1
            i += 1
        if j - i + 1 < best:
            best = j - i + 1

    return best

MOD = 998244353

def calculate_expected_operations(N, A):
    NN = 1 << N

    def fwht(a):
        i = 1
        while i < NN:
            j = 0
            while j < NN:
                for k in range(i):
                    (x, y) = (a[j + k], a[i + j + k])
                    (a[j + k], a[i + j + k]) = ((x + y) % MOD, (x - y) % MOD)
                j += i << 1
            i <<= 1

    def inv(x):
        return pow(x, MOD - 2, MOD)

    s = inv(sum(A) % MOD)
    for i in range(NN):
        A[i] = A[i] * s % MOD
    A[0] = (A[0] - 1) % MOD
    fwht(A)

    B = [-1] * NN
    B[0] = (NN - 1) % MOD
    fwht(B)

    C = [inv(A[i]) * B[i] % MOD for i in range(NN)]
    fwht(C)

    for i in range(NN):
        C[i] = C[i] * inv(NN) % MOD

    result = [(C[i] - C[0]) % MOD for i in range(NN)]
    return result

def stats_disc_distr(distrib):
    def check_errors(distrib):
        errors = 0
        if not isclose(sum((x[1] for x in distrib)), 1):
            errors += 1
        if not all((isinstance(x[0], int) or (isinstance(x[0], float) and x[0].is_integer()) for x in distrib)):
            errors += 2
        if errors > 0:
            return {
                1: "It's not a valid distribution",
                2: "All the variable values should be integers",
                3: "It's not a valid distribution and furthermore, one or more variable value are not integers"
            }[errors]
        return None

    def isclose(a, b, rel_tol=1e-09, abs_tol=0.0):
        return abs(a - b) <= max(rel_tol * max(abs(a), abs(b)), abs_tol)

    err = check_errors(distrib)
    if err:
        return err

    mean = sum((x[0] * x[1] for x in distrib))
    var = sum(((x[0] - mean) ** 2 * x[1] for x in distrib))
    std_dev = var ** 0.5

    return [mean, var, std_dev]

def reorder_sequence(N, A, B):
    ultimate_sum = 0
    for i in range(20):
        mask = 1 << i
        count_a = 0
        count_b = 0
        for a, b in zip(A, B):
            if a & mask > 0:
                count_a += 1
            if b & mask > 0:
                count_b += 1
        if count_a == 0 and count_b == 0:
            continue
        if count_a != count_b:
            ultimate_sum |= 1 << i
        elif N - count_a == count_b:
            return -1

    perm = [a ^ ultimate_sum for a in A]
    if sorted(perm) != sorted(B):
        return -1
    else:
        return perm

