from collections import deque

def shortest_path_with_obstacles(mat, k):
    m, n = len(mat), len(mat[0])
    q = deque([(0, 0, k, 0)])  # (row, col, remaining_k, steps)
    visited = set()

    if k >= m + n - 2:
        return m + n - 2

    while q:
        row, col, obstacles, steps = q.popleft()

        if row == m - 1 and col == n - 1:
            return steps

        for r, c in ((row, col + 1), (row + 1, col), (row - 1, col), (row, col - 1)):
            if 0 <= r < m and 0 <= c < n:
                k_rem = obstacles - mat[r][c]
                if mat[r][c] >= 0 and k_rem >= 0 and ((r, c, k_rem) not in visited):
                    q.append((r, c, k_rem, steps + 1))
                    visited.add((r, c, k_rem))

    return -1

