    """
    Computes the nth Fibonacci number using memoization to optimize performance.

    Parameters:
    n (int): The position in the Fibonacci sequence to compute.

    Returns:
    int: The Fibonacci number at position n.
    """
    cache = {}

    def fib(k):
        if k in cache:
            return cache[k]
        if k in [0, 1]:
            return k
        cache[k] = fib(k - 1) + fib(k - 2)
        return cache[k]

    return fib(n)

