def minimum_coin_permutations(n, p, s):
    # Create a mapping from the target permutation s to their indices
    index_map = {value: idx for idx, value in enumerate(s)}

    # Transform p to match the indices of s
    p_indices = [index_map[value] for value in p]

    # Calculate the initial cost
    min_coins = sum(abs(p_indices[i] - i) for i in range(n)) // 2

    # List to store the swap operations
    operations = []

    # Perform swaps to transform p_indices to the identity permutation
    while True:
        for i in range(n):
            if p_indices[i] < i:
                for j in range(p_indices[i], i):
                    if p_indices[j] >= i:
                        # Perform the swap
                        p_indices[i], p_indices[j] = p_indices[j], p_indices[i]
                        operations.append((i + 1, j + 1))  # Convert to 1-based index
                        break
                break
        else:
            break

    return min_coins, operations

