def min_candy(N, ratings):
    # Initialize arrays to store the number of candies each child gets
    L = [1] * N
    R = [1] * N

    # Traverse from left to right to ensure higher rating children get more candies than left neighbors
    for i in range(1, N):
        if ratings[i] > ratings[i - 1]:
            L[i] = L[i - 1] + 1

    # Traverse from right to left to ensure higher rating children get more candies than right neighbors
    for i in range(N - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            R[i] = R[i + 1] + 1

    # Calculate the total minimum number of candies needed
    total_candies = 0
    for i in range(N):
        total_candies += max(L[i], R[i])

    return total_candies

