def find_valid_a(n: int) -> str:
    def digits(n):
        rd = []
        while n:
            (n, d) = divmod(n, 10)
            rd.append(d)
        return list(reversed(rd))

    def _ifs(dn, i, j, ci, cj, al, ar):
        while i < j:
            di = dn[i] + 10 * ci
            dj = dn[j] - cj
            for (ci, cj) in ((0, 0), (0, 1), (1, 0), (1, 1)):
                d = di - ci
                if d < 0 or d > 18:
                    continue
                if dj + 10 * cj == d:
                    if d < 10:
                        if d == 0 and (not al):
                            return
                        al.append(d)
                        ar.append(0)
                    else:
                        al.append(9)
                        ar.append(d - 9)
                    break
            else:
                return
            i += 1
            j -= 1
        if i == j:
            d = dn[i] + 10 * ci - cj
            if d < 0 or d % 2:
                return
            al.append(d // 2)
        elif ci != cj:
            return
        return al + list(reversed(ar))

    def inv_fsum(dn):
        if dn[0] == 1:
            return _ifs(dn, 0, len(dn) - 1, 0, 0, [], []) or _ifs(dn, 1, len(dn) - 1, 1, 0, [], []) or [0]
        else:
            return _ifs(dn, 0, len(dn) - 1, 0, 0, [], []) or [0]

    dn = tuple(digits(n))
    result = inv_fsum(dn)
    return ''.join(map(str, result))

