                        q.appendleft((v + 1, t + cost1, cnt))
                        checked[v + 1][t + cost1] = cnt
                    else:
                        q.append((v + 1, 0, cnt + 1))
                        checked[v + 1][0] = cnt + 1

        if v != 0:
            cost2 = safety_islands[v] - safety_islands[v - 1]
            if t + cost2 <= g:
                if checked[v - 1][(t + cost2) % g] == -1:
                    if t + cost2 < g:
                        q.appendleft((v - 1, t + cost2, cnt))
                        checked[v - 1][t + cost2] = cnt
                    else:
                        q.append((v - 1, 0, cnt + 1))
                        checked[v - 1][0] = cnt + 1

    ans = 10 ** 18
    for i in range(m):
        for j in range(g):
