    for K in range(y):
        p = K + 1
        if y % p == 0:
            ans = 2 * (y // p)
        else:
            ans = 2 * (y // p + 1)

        mu = 0
        while mu < y:
            n1 = mu // M
            m1 = mu % M
            y2 = m1 * N + n1
            if y2 % (K + 1) == 0:
                ans -= 1
            mu += K + 1

        results.append(ans)

    return results

