def can_form_string_from_graph(n, m, edges):
    # Initialize the adjacency matrix
    s = [[0] * n for _ in range(n)]

    # Fill the adjacency matrix with edges
    for a, b in edges:
        s[a - 1][b - 1] = 1
        s[b - 1][a - 1] = 1

    # Set diagonal elements to 1 (self-loops, though not necessary for this problem)
    for i in range(n):
        s[i][i] = 1

    # Initialize the answer list
    answer = [0] * n

    # Assign 'b' to vertices that are fully connected
    for i in range(n):
        if all(s[i][j] == 1 for j in range(n)):
            answer[i] = 'b'

    # Assign 'a' to the first unassigned vertex and propagate
    for i in range(n):
        if answer[i] == 0:
            answer[i] = 'a'
            for j in range(n):
                if s[i][j] == 0:
                    answer[j] = 'c'
                elif s[i][j] == 1 and answer[j] != 'b':
                    answer[j] = 'a'
            break

    # Validate the assignment
    flag = True
    for i in range(n):
        for j in range(n):
            if s[i][j] == 1:
                if (answer[i] == 'a' and answer[j] == 'c') or (answer[i] == 'c' and answer[j] == 'a'):
                    flag = False
            if s[i][j] == 0:
                if abs(ord(answer[i]) - ord(answer[j])) < 2:
                    flag = False

    if flag:
        return True, ''.join(answer)
    else:
        return False, None

def count_paths_with_coins(N, K, arr):
    # Helper function to perform the recursive path counting with memoization
    def util(i, j, k):
        nonlocal dp
        # Base cases
        if i >= N or j >= N or k < 0:
            return 0
        if i == N - 1 and j == N - 1:
            if k - arr[i][j] == 0:
                return 1
            return 0
        if dp[i][j][k] != -1:
            return dp[i][j][k]

        # Recursive calls
        dp[i][j][k] = util(i + 1, j, k - arr[i][j]) + util(i, j + 1, k - arr[i][j])
        return dp[i][j][k]

    # Initialize the memoization table
    dp = [[[-1 for _ in range(K + 1)] for _ in range(N)] for _ in range(N)]

    # Start the recursive counting from the top-left corner
    return util(0, 0, K)

def find_potential_killers(N, reporting_list):
    # Create a dictionary to represent the reporting structure
    tree = {}

    # Initialize the tree with empty lists for each member
    for i in range(1, N + 1):
        tree[i] = []

    # Populate the tree based on the reporting list
    for i in range(N):
        reporter = reporting_list[i]
        if reporter != 0:
            tree[reporter].append(i + 1)

    # Find all members who nobody reports to (potential killers)
    potential_killers = [i for i in range(1, N + 1) if not tree[i]]

    return potential_killers

def find_safe_position(n: int, k: int) -> int:
    def josephus_(n: int, k: int) -> int:
        if n == 0:
            return 0
        else:
            return (josephus_(n - 1, k) + k) % n

    return josephus_(n, k) + 1

