def is_valid_ipv4(ip_address: str) -> int:
    def has_leading_zero(n: str) -> bool:
        return len(n) > 1 and n[0] == '0'

    def in_range(n: int) -> bool:
        return 0 <= n <= 255

    parts = ip_address.split('.')

    if len(parts) != 4:
        return 0

    for part in parts:
        if len(part) == 0 or has_leading_zero(part):
            return 0
        try:
            num = int(part)
            if not in_range(num):
                return 0
        except ValueError:
            return 0

    return 1

def can_transform(start: str, end: str) -> bool:
    # Check if the lengths of start and end are the same
    if len(start) != len(end):
        return False

    # Initialize pointers for start and end
    i, j = 0, 0

    # Iterate through the strings
    while i < len(start) and j < len(end):
        # Skip 'X' characters
        while i < len(start) and start[i] == 'X':
            i += 1
        while j < len(end) and end[j] == 'X':
            j += 1

        # If one of the pointers has reached the end, check if both have
        if i == len(start) or j == len(end):
            return i == len(start) and j == len(end)

        # If the characters at the current positions are different, return False
        if start[i] != end[j]:
            return False

        # If both characters are 'L', 'L' in start should be to the left of 'L' in end
        if start[i] == 'L' and i < j:
            return False

        # If both characters are 'R', 'R' in start should be to the right of 'R' in end
        if start[i] == 'R' and i > j:
            return False

        # Move to the next characters
        i += 1
        j += 1

    # If both pointers have reached the end, return True
    return i == len(start) and j == len(end)

def calculate_max_distance_and_cost(test_cases):
    def bfs(x, n, G):
        b = [False] * (n + 1)  # an array of false flags to keep track of vertices visited
        memo = ["p"] * (n + 1)
        l = 0
        c = 0
        q = []
        q.append(x)
        memo[x] = 0
        while q:
            top = q.pop(0)
            b[top] = True
            for j in G[top]:
                if memo[j[0]] == "p":
                    q.append(j[0])
                    memo[j[0]] = memo[top] + j[1]  # time of discovery(level) of child is time of discovery(level) of parent + 1
                    b[j[0]] = True
                    if memo[j[0]] > l:
                        l = memo[j[0]]
                        c = j[0]
        return l, c

    results = []
    for test_case in test_cases:
        n, edges = test_case
        G = [[] for _ in range(n + 1)]
        for x, y, z in edges:
            G[x].append((y, z))  # undirected graph has edge from u to v.
            G[y].append((x, z))  # also has edge from v to u.

        upto, new = bfs(1, n, G)
        found = False
        while not found:
            j = bfs(new, n, G)
            if upto < j[0]:
                upto = j[0]
                new = j[1]
            else:
                found = True

        if upto < 100:
