    maxans = 0
    cntmax = []

    while l + 1 < r:
        mid = (l + r) // 2
        if mid > maxans:
            cntnow = []
            mins = mini_in_window(heights, n, mid)
            maxes = maxi_in_window(heights, n, mid)
            for i in range(len(mins)):
                if heights[maxes[i]] - heights[mins[i]] <= k:
                    cntnow.append((mins[i] + 1, maxes[i] + 1))
            if cntnow:
                l = mid
                cntmax = cntnow[:]
            else:
                r = mid

    max_books = l
    periods = cntmax

    return max_books, periods

def are_orders_deliverable_together(n, m, fast_roads, queries):
    def find(parent, i):
        if parent[i] == i:
            return i
        parent[i] = find(parent, parent[i])
        return parent[i]

    def union(parent, rank, x, y):
        rootx = find(parent, x)
        rooty = find(parent, y)
        if rootx != rooty:
            if rank[rootx] < rank[rooty]:
                parent[rootx] = rooty
            elif rank[rootx] > rank[rooty]:
                parent[rooty] = rootx
            else:
                parent[rooty] = rootx
                rank[rootx] += 1

    parent = [i for i in range(n)]
    rank = [0 for i in range(n)]

    for x, y in fast_roads:
        union(parent, rank, x, y)

    results = []
    for x, y in queries:
        if find(parent, x) == find(parent, y):
            results.append("YO")
        else:
            results.append("NO")

    return results

