def can_rabbits_play(n, k, operations):
    def root(x):
        if x == p[x]:
            return x
        p[x] = y = root(p[x])
        return y

    def unite(x, y):
        px = root(x)
        py = root(y)
        if px < py:
            p[py] = px
        else:
            p[px] = py

    emp = {}
    sq = int(k ** 0.5) + 1
    results = []

    for i in range(sq):
        s = set()
        for j in range(i * sq, min(i * sq + sq, k)):
            (t, a, b) = operations[j]
            if t == 3:
                continue
            e = (a, b)
            if emp.get(e, 0):
                s.add(e)
            emp[e] = 0

        p = list(range(n))
        for ((v, w), d) in emp.items():
            if d == 1:
                unite(v, w)

        G0 = [[] for _ in range(n)]
        emp0 = {}
        for (a, b) in s:
            pa = root(a)
            pb = root(b)
            if pa == pb:
                continue
            e = (pa, pb) if pa < pb else (pb, pa)
            if e in emp0:
                (e1, e2) = emp0[e]
                e1[1] = e2[1] = e1[1] + 1
            else:
                e1 = [pb, 1]
                e2 = [pa, 1]
                G0[pa].append(e1)
                G0[pb].append(e2)
                emp0[e] = (e1, e2)

        for j in range(i * sq, min(i * sq + sq, k)):
            (t, a, b) = operations[j]
            pa = root(a)
            pb = root(b)
            e = (pa, pb) if pa < pb else (pb, pa)
            if t == 1:
                emp[a, b] = 1
                if pa == pb:
                    continue
                if e not in emp0:
                    e1 = [pb, 1]
                    e2 = [pa, 1]
                    G0[pa].append(e1)
                    G0[pb].append(e2)
                    emp0[e] = (e1, e2)
                else:
                    (e1, e2) = emp0[e]
                    e1[1] = e2[1] = e1[1] + 1
            elif t == 2:
                emp[a, b] = 0
                if pa == pb:
                    continue
                (e1, e2) = emp0[e]
                e1[1] = e2[1] = e1[1] - 1
            elif t == 3:
                if pa == pb:
                    results.append('YES')
                else:
                    que = deque([pa])
                    used = [0] * n
                    used[pa] = 1
                    found = False
                    while que:
                        v = que.popleft()
                        for (w, d) in G0[v]:
                            if d and not used[w]:
                                if w == pb:
                                    results.append('YES')
                                    found = True
                                    break
                                used[w] = 1
                                que.append(w)
                        if found:
                            break
                    if not found:
                        results.append('NO')

    return results

