def can_first_player_win(test_cases):
    def g(a, b):
        if a > b:
            a, b = b, a
        if b == a:
            return 0
        if b % a == 0:
            return b // a - 1
        r = g(b % a, a)
        q = b // a
        if r >= q:
            return q - 1
        else:
            return q

    def mex(x):
        n = len(x)
        for i in range(n):
            if i not in x:
                return i
        return n

    def g2(a, b):
        if a == b:
            return 0
        if a > b:
            a, b = b, a
        if b % a == 0:
            return b // a - 1
        q = b // a
        x = {}
        r = b % a
        for i in range(q):
            x[g2(r + i * a, a)] = True
        return mex(x)

    results = []
    for pairs in test_cases:
        x = 0
        for a, b in pairs:
            x ^= g(a, b)
        results.append("YES" if x else "NO")
    return results

def find_greatest_difference_couple(arr):
    if not arr:
        return False

    def difference(couple):
        num1, num2 = map(int, couple.split('-'))
        return abs(num1 - num2)

    greatest_diff_couple = max(arr, key=difference, default=None)

    if greatest_diff_couple and difference(greatest_diff_couple) > 0:
        return greatest_diff_couple
    else:
        return False

