def count_pairs_with_distance(n, k, edges):
    if n == 1:
        return 0

    # Build the tree as an adjacency list
    tree = {i: [] for i in range(1, n + 1)}
    for a, b in edges:
        tree[a].append(b)
        tree[b].append(a)

    # Initialize distance array and answer array
    d = [[0 for _ in range(k + 3)] for _ in range(n + 1)]
    for i in range(1, n + 1):
        d[i][0] = 1
    ans = [0 for _ in range(n + 1)]

    # First DFS to populate the distance array
    def dfs(graph, n, currnode):
        visited = [False for _ in range(n + 1)]
        stack = [currnode]
        index = [0 for _ in range(n + 1)]
        parent = [0 for _ in range(n + 1)]
        while stack:
            currnode = stack[-1]
            if not visited[currnode]:
                visited[currnode] = True
            for i in range(index[currnode], len(graph[currnode])):
                neighbour = graph[currnode][i]
                if not visited[neighbour]:
                    visited[neighbour] = True
                    stack.append(neighbour)
                    parent[neighbour] = currnode
                    index[currnode] += 1
                    break
            else:
                for i in range(k + 2):
                    d[parent[currnode]][i + 1] += d[currnode][i]
                stack.pop()
        ans[1] = d[1][k]
        return

    dfs(tree, n, 1)

    # Second DFS to finalize the answer
    def dfs1(graph, n, currnode):
        visited = [False for _ in range(n + 1)]
        stack = [currnode]
        index = [0 for _ in range(n + 1)]
        parent = [0 for _ in range(n + 1)]
        while stack:
            currnode = stack[-1]
            if not visited[currnode]:
                visited[currnode] = True
            for i in range(index[currnode], len(graph[currnode])):
                neighbour = graph[currnode][i]
                if not visited[neighbour]:
                    visited[neighbour] = True
                    stack.append(neighbour)
                    parent[neighbour] = currnode
                    index[currnode] += 1
                    for i in range(k + 2):
                        d[currnode][i + 1] -= d[neighbour][i]
                    for i in range(k + 2):
                        d[neighbour][i + 1] += d[currnode][i]
                    ans[neighbour] = d[neighbour][k]
                    break
            else:
                for i in range(k + 2):
                    d[currnode][i + 1] -= d[parent[currnode]][i]
                for i in range(k + 2):
                    d[parent[currnode]][i + 1] += d[currnode][i]
                stack.pop()
        return

    dfs1(tree, n, 1)

    # Return the number of pairs with distance k
    return sum(ans[1:]) // 2

