def generate_tribonacci_sequence(signature, n):
    # Ensure the signature has exactly 3 elements
    if len(signature) != 3:
        raise ValueError("Signature must contain exactly 3 numbers.")

    # Handle the case where n is 0
    if n == 0:
        return []

    # Initialize the result with the first n elements of the signature
    res = signature[:n]

    # Generate the sequence up to n elements
    for i in range(n - 3):
        res.append(sum(res[-3:]))

    return res

