    topper = ''
    topscore = 0
    toppers = []

    for name, score in rounds:
        if name in scores:
            scores[name] += score
        else:
            scores[name] = score

        temp = max(scores, key=scores.get)
        tc = scores[temp]
        current_toppers = [key for key in scores if scores[key] == tc]

        if len(current_toppers) == 1:
            topper = current_toppers[0]
            topscore = tc
            toppers = current_toppers
