    if n == 1:
        return dessert_costs[0]

    dp = [0] * n
    dp[0] = dessert_costs[0]
    dp[1] = dessert_costs[1]

    for i in range(2, n):
        dp[i] = min(dp[i - 2], dp[i - 1]) + dessert_costs[i]

    reversed_costs = dessert_costs[::-1]
    dp1 = [0] * n
    dp1[0] = reversed_costs[0]
    dp1[1] = reversed_costs[1]

    for i in range(2, n):
