def determine_winner(N):
    oddsum = 1
    evensum = 0
    totsteps = 0

    num = N
    while num > 1:
        if num % 2 == 0:
            evensum += num
            num //= 2
        else:
            oddsum += num
            num = (3 * num) + 1
        totsteps += 1

    evenrem = evensum % totsteps
    oddrem = oddsum % totsteps

    if oddrem > evenrem:
        return "Odd Rules"
    elif oddrem < evenrem:
        return "Even Rules"
    else:
        return "Tie"

