    if Y >= X:
        if max_sadness % Y == 0:
            n_blimps = max_sadness // Y
        else:
            n_blimps = max_sadness // Y + 1
    else:
        for target_city in range(len(cities_sadness) - 1, -1, -1):
            if cities_sadness[target_city] > 0:
