def merge(x, y):
    if len(x) > len(y):
        (x, y) = (y, x)
    for i in x:
        y[i] = y[i] + x[i] if i in y else x[i]
    return (y, y)

def NC_Dij(lis, start):
    ret = [float('inf')] * len(lis)
    ret[start] = 0
    q = deque([start])
    plis = [i for i in range(len(lis))]
    while len(q) > 0:
        now = q.popleft()
        for nex in lis[now]:
            if ret[nex] > ret[now] + 1:
                ret[nex] = ret[now] + 1
                plis[nex] = now
                q.append(nex)
    return (ret, plis)

def count_final_trees(T, test_cases):
    mod = 10 ** 9 + 7
    results = []

    for case in test_cases:
        N, edges, values = case
        lis = [[] for _ in range(N)]
        for u, v in edges:
            lis[u - 1].append(v - 1)
            lis[v - 1].append(u - 1)

        (dlis, P) = NC_Dij(lis, 0)
        chnum = [0] * N
        for i in range(1, N):
            chnum[P[i]] += 1

        cds = [{} for _ in range(N)]
        allsum = [0] * N
        q = deque([])
        leaf = [False] * N
        ans = 0

        for i in range(N):
            if chnum[i] == 0:
                q.append(i)
                leaf[i] = True

        while q:
            v = q.popleft()
            nans = allsum[v] if values[v] not in cds[v] else allsum[v] - cds[v][values[v]]
            if leaf[v]:
                nans = 1
            nans %= mod
            ans += nans
            ans %= mod
            if values[v] not in cds[v]:
                cds[v][values[v]] = 0
            cds[v][values[v]] += nans
            cds[v][values[v]] %= mod
            if P[v] != v:
                chnum[P[v]] -= 1
                (cds[P[v]], cds[v]) = merge(cds[P[v]], cds[v])
                allsum[P[v]] = (allsum[P[v]] + allsum[v] + nans) % mod
                if chnum[P[v]] == 0:
                    q.append(P[v])

