def find_max_subarray_sum(arr, N, X):
    sum = 0
    ans = 0
    i, j = 0, 0

    while j < N:
        sum += arr[j]

        if sum < X:
            ans = max(ans, sum)
            j += 1
        elif sum == X:
            return X
        else:
            while sum > X:
                sum -= arr[i]
                i += 1
            ans = max(ans, sum)
            j += 1

    return ans

