def max_dot_product(N, M, A, B):
    # Initialize a 2D DP array with -1
    dp = [[-1 for _ in range(M)] for _ in range(N)]

    def solve(i, j, d):
        # Base case: if we have reached the end of either array
        if i == N or j == M:
            return 0
        # If the value is already computed, return it
        if dp[i][j] != -1:
            return dp[i][j]
        # If we can still insert zeros
        if d > 0:
            dp[i][j] = max(A[i] * B[j] + solve(i + 1, j + 1, d), solve(i + 1, j, d - 1))
        else:
            dp[i][j] = A[i] * B[j] + solve(i + 1, j + 1, d)
        return dp[i][j]

    # Start the recursive function with initial parameters
    return solve(0, 0, N - M)

def can_form_rectangles(n, sticks):
    if n == 1:
        # For n == 1, we only need to check if all sticks are the same length
        if sticks[0] == sticks[1] and sticks[2] == sticks[3]:
            return 'YES'
        else:
            return 'NO'

    # Sort the sticks to facilitate pairing
    sticks.sort()

    # Calculate the expected area of each rectangle
    expected_area = sticks[0] * sticks[-1]

    # Check pairs of sticks to form rectangles
    for j in range(n):
        left_pair = sticks[2 * j] == sticks[2 * j + 1]
        right_pair = sticks[4 * n - 2 * j - 2] == sticks[4 * n - 2 * j - 1]
        area_check = sticks[2 * j] * sticks[4 * n - 2 * j - 1] == expected_area

        if not (left_pair and right_pair and area_check):
            return 'NO'

    return 'YES'

