from heapq import heappop, heappush

class WeightedEdge:
    def __init__(self, a, b, weight):
        self.a = a
        self.b = b
        self.weight = weight

    def __repr__(self):
        return '(%d - %d: %d)' % (self.a, self.b, self.weight)

    def __lt__(self, other):
        return self.a < other.b

class EdgeWeightedGraph:
    def __init__(self, V):
        self.__adj = [[] for _ in range(V + 1)]

    def add_edge(self, a, b, weight):
        self.__adj[a].append(WeightedEdge(a, b, weight))
        self.__adj[b].append(WeightedEdge(b, a, weight))

    def adj(self, a):
        return self.__adj[a]

    def num_nodes(self):
        return len(self.__adj) - 1

class Dijkstra:
    def __init__(self, graph, s, t):
        self.dist_to = [float('inf') for _ in range(graph.num_nodes() + 1)]
        self.dist_to[s] = 0
        pq = []
        heappush(pq, (0, s))
        while pq:
            (w, a) = heappop(pq)
            if a == t:
                return
            if self.dist_to[a] < w:
                continue
            for edge in graph.adj(a):
                if self.dist_to[edge.b] > self.dist_to[a] + edge.weight:
                    self.dist_to[edge.b] = self.dist_to[a] + edge.weight
                    heappush(pq, (self.dist_to[edge.b], edge.b))

def find_min_cost_or_time(n, m, edges, queries):
    g_cost = EdgeWeightedGraph(m)
    g_time = EdgeWeightedGraph(m)

    for a, b, cost, time in edges:
        g_cost.add_edge(a, b, cost)
        g_time.add_edge(a, b, time)

    results = []
    for p, q, r in queries:
        if r == 0:
            fw_cost = Dijkstra(g_cost, p, q)
            results.append(fw_cost.dist_to[q])
        else:
            fw_time = Dijkstra(g_time, p, q)
            results.append(fw_time.dist_to[q])

    return results

def calculate_carpet_cost(room_width, room_length, roll_width, roll_cost):
    # Ensure room_width and room_length are sorted such that room_width <= room_length
    (room_width, room_length) = sorted((room_width, room_length))

    # Check for invalid dimensions
    if room_width == 0 or room_length == 0:
        return "error"

    # Check if the roll width is sufficient to cover the room width
    if roll_width < room_width:
        return "error"

    # Calculate the cost based on the minimal required length of carpet
    if roll_width >= room_length:
        # If the roll width is greater than or equal to the room length, we can use the room length
        cost = room_length * roll_width * roll_cost
    else:
        # Otherwise, we need to use the room width (since it's the smaller dimension)
        cost = room_width * roll_width * roll_cost

    # Return the cost rounded to two decimal places
    return round(cost, 2)

