def repeated_string_match(A: str, B: str) -> int:
    if not set(B).issubset(set(A)):
        return -1

    max_rep = len(B) // len(A) + 3
    A_new = A

    for i in range(1, max_rep):
        if B in A_new:
            return i
        A_new += A

    return -1

