def find_carmichael_period(N: int) -> int:
    def gcd(m, n):
        while n:
            (m, n) = (n, m % n)
        return m

    def lcm(m, n):
        return m // gcd(m, n) * n

    def carmichael(x):
        r = 1
        b = 0
        while x & 1 == 0:
            b += 1
            x >>= 1
        if b > 1:
            r = 2 if b == 2 else 2 ** (b - 2)
        y = 3
        while y * y <= x:
            if x % y == 0:
                c = 0
                while x % y == 0:
                    x //= y
                    c += 1
                r = lcm(r, (y - 1) * y ** (c - 1))
            y += 1
        if x > 1:
            r = lcm(r, x - 1)
        return r

    def solve(x, c):
        if c == 1:
            return 1
        x = x % c
        sq = int(c ** 0.5) + 1
        mp = {}
        y = 1
        for i in range(sq):
            mp[y] = i
            y = y * x % c
            if y == 1:
                return i + 1
            if y in mp:
                return -1
        z = 1
        for i in range(sq):
            z = z * y % c
            if z in mp:
                return sq * (i + 1) - mp[z]
        return -1

    c = carmichael(N)
    k = solve(N, c)
    if k == -1 or pow(N, k, c) != 1 % c:
        return -1
    else:
        return k

def find_equidistant_point(lines, EPS=1e-09):
    def line_cross_point(P1, P2, Q1, Q2):
        (x0, y0) = P1
        (x1, y1) = P2
        (x2, y2) = Q1
        (x3, y3) = Q2
        dx0 = x1 - x0
        dy0 = y1 - y0
        dx1 = x3 - x2
        dy1 = y3 - y2
        s = (y0 - y2) * dx1 - (x0 - x2) * dy1
        sm = dx0 * dy1 - dy0 * dx1
        if -EPS < sm < EPS:
            return None
        return (x0 + s * dx0 / sm, y0 + s * dy0 / sm)

    def bisector(P1, P2, Q1, Q2):
        (x0, y0) = P1
        (x1, y1) = P2
        (x2, y2) = Q1
        (x3, y3) = Q2
        dx0 = x1 - x0
        dy0 = y1 - y0
        dx1 = x3 - x2
        dy1 = y3 - y2
        cp = line_cross_point(P1, P2, Q1, Q2)
        if cp is None:
            return None
        (cx, cy) = cp
        d0 = (dx0 ** 2 + dy0 ** 2) ** 0.5
        d1 = (dx1 ** 2 + dy1 ** 2) ** 0.5
        return [((cx, cy), (cx + (dx0 * d1 + dx1 * d0), cy + (dy0 * d1 + dy1 * d0))), ((cx, cy), (cx + (dx0 * d1 - dx1 * d0), cy + (dy0 * d1 - dy1 * d0)))]

    def line_point_dist2(p1, p2, q):
        (x, y) = q
        (x1, y1) = p1
        (x2, y2) = p2
        dx = x2 - x1
        dy = y2 - y1
        dd = dx ** 2 + dy ** 2
        sv = (x - x1) * dy - (y - y1) * dx
        return abs(sv / dd ** 0.5)

    def check(LS, q):
        ds = [line_point_dist2(p1, p2, q) for (p1, p2) in LS]
        return all((abs(ds[0] - e) < EPS for e in ds))

    N = len(lines)
    if N <= 2:
        return "Many"

    s = []
    for i in range(N):
        (p1, p2) = lines[i]
        for j in range(i):
            (q1, q2) = lines[j]
            bs = bisector(p1, p2, q1, q2)
            if bs is None:
                continue
            s.append(bs)
            if len(s) > 1:
                break
        else:
            continue
        break

    if len(s) < 2:
        return "None"

