def assign_fish_colors(n, points):
    edges = []
    edges_dico = {}
    count = defaultdict(int)
    graph = defaultdict(lambda: defaultdict(int))

    for u, v in points:
        count[u] += 1
        count[-v] += 1
        graph[u][-v] = 1
        graph[-v][u] = 1
        edges.append((u, -v))
        edges_dico[u, -v] = True

    odds = []
    for u in count:
        if count[u] % 2 == 1:
            odds.append(u)

    A = 2 * 10 ** 6 + 1
    B = 2 * 10 ** 6 + 2

    for u in odds:
        if u > 0:
            graph[A][u] = 1
            graph[u][A] = 1
            count[A] += 1
        else:
            graph[B][u] = 1
            graph[u][B] = 1
            count[B] += 1

    if count[A] % 2 == 1:
        graph[A][B] = 1
        graph[B][A] = 1

    count_deleted = 0
    nodes = graph.keys()

    for u in nodes:
        current = u
        color = 'r'
        while True:
            color = 'b' if color == 'r' else 'r'
            end = True
            edge_to_delete = None
            for neighbour in graph[current]:
                if graph[current][neighbour] == 1:
                    edge_to_delete = (current, neighbour)
                    if (neighbour, current) in edges_dico:
                        edges_dico[neighbour, current] = color
                    if (current, neighbour) in edges_dico:
                        edges_dico[current, neighbour] = color
                    count_deleted += 1
                    current = neighbour
                    end = False
                    break
            if end:
                break
