def bsearch(inv, y):
    lb = 1
    ub = y * 5
    while ub - lb > 1:
        mid = (ub + lb) // 2
        if inv(mid) >= y:
            ub = mid
        elif inv(mid) < y:
            lb = mid
    if inv(lb) == y:
        return lb
    else:
        return ub

