def find_longest_sleep_period(n, alarms):
    def to_minutes(a):
        return 60 * a[0] + a[1]

    def to_hours(a):
        return (a // 60, a % 60)

    def pad(a):
        return ('0' if a < 10 else '') + str(a)

    # Convert all alarm times to minutes and sort them
    alarm_minutes = sorted(to_minutes(alarm) for alarm in alarms)

    longest = 0
    for i in range(1, n):
        longest = max(longest, alarm_minutes[i] - alarm_minutes[i - 1])

    # Consider the wrap-around case from the last alarm to the first alarm of the next day
    longest = max(longest, 60 * 24 + alarm_minutes[0] - alarm_minutes[-1])

    # Subtract 1 minute because the alarm rings for exactly one minute
    longest -= 1

    # Convert the longest sleep period back to hours and minutes
    (hours, minutes) = to_hours(longest)

    # Format the result as "hh:mm"
    return f"{pad(hours)}:{pad(minutes)}"

def can_form_square(matchsticks):
    if len(matchsticks) < 4:
        return False
    total_length = sum(matchsticks)
    if total_length % 4 != 0:
        return False
    side_length = total_length // 4
    matchsticks.sort(reverse=True)
    if side_length < matchsticks[0]:
        return False

    def dfs(used, start_index, target, remain_rounds):
        if remain_rounds == 0:
            return True
        for i in range(start_index, len(matchsticks)):
            if i in used:
                continue
            num = matchsticks[i]
            if num > target:
                continue
            new_used = used | {i}
            if num == target:
                if dfs(new_used, 0, side_length, remain_rounds - 1):
                    return True
            else:
                if dfs(new_used, i + 1, target - num, remain_rounds):
                    return True
        return False

    return dfs(set(), 0, side_length, 4)

