    arr (list of int): The array of integers to be split.

    Returns:
    int: The maximum number of points Nikita can score.
    """
    def solve(a):
        s = sum(a)
        if s % 2 != 0:
            return 0
        s //= 2
        t = 0
        for i in range(len(a)):
            t += a[i]
            if t == s:
                return 1 + max(solve(a[:i + 1]), solve(a[i + 1:]))
            if t > s:
                return 0

    return solve(arr)

