        else:
            p = (lr if c == 'R' else ll)[p]

    result = []
    q = p
    while p != -1:
        result.append(bracket_sequence[p])
        p = ll[p]
    result.reverse()
    del result[-1]
    while q != n:
        result.append(bracket_sequence[q])
        q = lr[q]

    return ''.join(result)

def compress_sentence(sentence: str) -> str:
    ref = []
    for word in sentence.lower().split():
        if word not in ref:
            ref.append(word)
    return ''.join([str(ref.index(word)) for word in sentence.lower().split()])

def longest_alternating_subsequence(nums):
    if not nums:
        return 0

    n = len(nums)
    if n == 1:
        return 1

    # Initialize state variables
    increasing = 1
    decreasing = 1

    for i in range(1, n):
        if nums[i] > nums[i - 1]:
            increasing = decreasing + 1
        elif nums[i] < nums[i - 1]:
            decreasing = increasing + 1

    return max(increasing, decreasing)

