def evaluate_postfix_expression(S: str) -> int:
    stack = []
    for char in S:
        if char in ['+', '-', '/', '*']:
            y = stack.pop()
            x = stack.pop()
            if char == '+':
                stack.append(x + y)
            elif char == '-':
                stack.append(x - y)
            elif char == '*':
                stack.append(x * y)
            elif char == '/':
                stack.append(x // y)
        else:
            stack.append(int(char))
    return stack[-1]

def count_subsets_with_sum(arr: list, sum_value: int) -> int:
    m = 1000000007
    n = len(arr)
    t = [[0 for _ in range(sum_value + 1)] for _ in range(n + 1)]
    t[0][0] = 1

    for i in range(1, n + 1):
        for j in range(sum_value + 1):
            if arr[i - 1] <= j:
                t[i][j] = (t[i - 1][j - arr[i - 1]] + t[i - 1][j]) % m
            else:
                t[i][j] = t[i - 1][j] % m

    return t[n][sum_value] % m

def evaluate_set_expression(sets, expression):
    def rpn(str):
        r = []
        stack = []
        for i in range(len(str)):
            c = str[i]
            if c in 'idsu':
                while stack and stack[-1] in 'idsuc':
                    r.append(stack.pop())
                stack.append(c)
            elif c == 'c':
                stack.append(c)
            elif c == '(':
                stack.append(c)
            elif c == ')':
                while stack and stack[-1] != '(':
                    r.append(stack.pop())
                stack.pop()  # Remove '('
            else:
                r.append(c)
        while stack:
            r.append(stack.pop())
        return r

    def intersect(a, b):
        return [e for e in a if e in b]

    def union(a, b):
        return list(set(a + b))

    def diff(a, b):
        return [e for e in a if e not in b]

    def universal(sets):
        return list(set(sum(sets.values(), [])))

    def calc(rpn, sets):
        stack = []
        U = universal(sets)
        for c in rpn:
            if c in 'iuds':
                op2 = stack.pop()
                op1 = stack.pop()
                if c == 'i':
                    stack.append(intersect(op1, op2))
                elif c == 'u':
                    stack.append(union(op1, op2))
                elif c == 'd':
                    stack.append(diff(op1, op2))
                elif c == 's':
                    stack.append(union(diff(op1, op2), diff(op2, op1)))
            elif c == 'c':
                op1 = stack.pop()
                stack.append(diff(U, op1))
            else:
                stack.append(sets[c])
        return stack.pop()

    rpn_expression = rpn(expression)
    result = calc(rpn_expression, sets)
    result.sort()
    return ' '.join(map(str, result)) if result else 'NULL'

