def restore_operations(n, m, k, pictures):
    def countHoles(pic):
        h = 0
        for i in range(1, len(pic) - 1):
            for j in range(1, len(pic[i]) - 1):
                h += pic[i + 1][j] == pic[i - 1][j] == pic[i][j - 1] == pic[i][j + 1] and pic[i + 1][j] != pic[i][j]
        return h

    def findDiff(pic1, pic2):
        diff = []
        for i in range(len(pic1)):
            for j in range(len(pic1[i])):
                if pic1[i][j] != pic2[i][j]:
                    diff += [(i, j)]
        return diff

    pics = [(i, pic) for i, pic in enumerate(pictures)]
    sortpics = sorted(pics, key=lambda p: -countHoles(p[1]))
    prevpic = sortpics[0][1]
    op = []
    for (i, pic) in sortpics[1:]:
        diff = findDiff(prevpic, pic)
