    for (a, b) in edges:
        g[a].append(b)

    # Set to store unique paths
    path = set()

    # Helper function to perform DFS and count paths
    def helper(node, prev, p):
        if node == d:
            path.add(tuple(p + [node]))
            return
        if node in p:
            return
        for neig in g[node]:
            if neig != prev:
                helper(neig, node, p + [node])

