def count_lattice_points(R: int) -> int:
    if R == 0:
        return 0

    count = 4  # Initial count for (0, R), (0, -R), (R, 0), (-R, 0)

    for i in range(1, R):
        t = math.sqrt(R * R - i * i)
        if t == int(t):
            count += 4

    return count

