def replace_words_in_sentence(roots, sentence):
    def build_trie(roots):
        trie = {}
        for word in roots:
            current = trie
            for char in word:
                if char not in current:
                    current[char] = {}
                current = current[char]
            current['#'] = word
        return trie

    def find_root(word, trie):
        current = trie
        for char in word:
            if char not in current:
                break
            current = current[char]
            if '#' in current:
                return current['#']
        return word

