        mods[digsum(i)][i % K] += 1

    for i in range(1, maxDIGSUM):
        for j in range(K):
            mods[i][j] += mods[i - 1][j]

    res = 0
    last = A - (A % FAC) + FAC
    res += simpleCount(A, last)
    first = B - (B % FAC)
    res += simpleCount(first, B)

    su = digsum(last) - 1
    i = (last // FAC) % 10
    for x in range(last, first, FAC):
        m = x % K
        if m == 0:
            m = K
        if i % 10:
