def solve_n_queens(n: int) -> list[list[str]]:
    def helper(current_index: int, aux: list[list[str]], rows_with_queen: list[int], all_solutions: list[list[list[str]]]):
        for i in range(n):
            if i not in rows_with_queen:
                (x, y) = (current_index - 1, i - 1)
                while x >= 0 and y >= 0 and aux[x][y] != 'Q':
                    x -= 1
                    y -= 1
                if x != -1 and y != -1:
                    continue
                (x, y) = (current_index - 1, i + 1)
                while x >= 0 and y < n and aux[x][y] != 'Q':
                    x -= 1
                    y += 1
                if x != -1 and y != n:
                    continue
                aux[current_index][i] = 'Q'
                rows_with_queen.append(i)
                if current_index == n - 1:
                    solution = [row[:] for row in aux]
                    all_solutions.append(solution)
                else:
                    helper(current_index + 1, aux, rows_with_queen, all_solutions)
                aux[current_index][i] = '.'
                rows_with_queen.pop()

    aux = [['.' for _ in range(n)] for _ in range(n)]
    rows_with_queen = []
    all_solutions = []
    helper(0, aux, rows_with_queen, all_solutions)

    result = []
    for sol in all_solutions:
        result.append([''.join(row) for row in sol])

    return result

def calculate_max_sum(N, M, matrix, pairs):
    E1 = 0
    E2 = 0
    E1_valid = True
    E2_valid = True

    for (i, j) in pairs:
        if 1 <= i <= N and 1 <= j <= M:
            E1 += matrix[i - 1][j - 1]
        else:
            E1_valid = False

        if 1 <= j <= N and 1 <= i <= M:
            E2 += matrix[j - 1][i - 1]
        else:
            E2_valid = False

    if not E1_valid:
        E1 = -1
    if not E2_valid:
        E2 = -1

    return max(E1, E2)

from itertools import product, permutations, combinations

def minimize_experience_difference(n, likes, bosses):
    names = {}
    nex = 0
    mama = 128
    liking = [0] * mama
    likes_matrix = [[0] * 7 for _ in range(7)]

    def getName(name):
        nonlocal nex
        if name in names:
            return names[name]
        names[name] = nex
        nex += 1
        return names[name]

    for a, _, c in likes:
        likes_matrix[getName(a)][getName(c)] = 1

    part = set()
    dipart = 10 ** 10

    for i in range(1, 4):
        for j in range(i, 7):
            k = 7 - i - j
            if k < j:
                continue
            for per in permutations(bosses):
                aa = (per[0] // i, per[1] // j, per[2] // k)
                difi = max(aa) - min(aa)
                if difi < dipart:
                    dipart = difi
                    part = set()
                    part.add((i, j, k))
                elif difi == dipart:
                    part.add((i, j, k))

    for i, j in product(range(7), repeat=2):
        if likes_matrix[i][j] == 0:
            continue
        mask = 1 << i | 1 << j
        for k in range(mama):
            if k & mask == mask:
                liking[k] += 1

    nums = list(range(7))

    def tonum(ite):
        r = 0
        for nu in ite:
            r |= 1 << nu
        return r

    bea = 0
    for a, b, c in part:
        for pera in combinations(range(7), a):
            lefta = [x for x in nums if x not in pera]
            for perb in combinations(lefta, b):
                perc = [x for x in lefta if x not in perb]
                susu = liking[tonum(pera)] + liking[tonum(perb)] + liking[tonum(perc)]
                if susu > bea:
                    bea = susu

    return dipart, bea

