    return dfs_connected(adj_edges)

def determine_game_winner(s, k=None):
    """
    Determines the winner of the game for a given string `s` and initial position `k`.

    Parameters:
    - s (str): The input string consisting of lowercase English letters.
    - k (int, optional): The initial position `k`. If None, the function returns the winner for all possible `k` values.

    Returns:
    - str or list of str: The winner ("Mike" or "Ann") for the given `k` or a list of winners for all possible `k` values.
    """
    if k is not None and (k < 0 or k >= len(s)):
        raise ValueError("k must be within the range [0, len(s) - 1]")

    mn = s[0]
    winners = []

    for i in range(len(s)):
        mn = min(mn, s[i])
        if s[i] > mn:
            winners.append('Ann')
        else:
            winners.append('Mike')

    if k is None:
        return winners
    else:
        return winners[k]

