from heapq import heapify, heappop, heappush

def reconstruct_graph(n, m, edges):
    # Sort edges based on weight and inclusion in MST
    sorted_indices = sorted(range(m), key=lambda x: edges[x][0] * 10000000000 - edges[x][1])

    # Initialize the list to store the reconstructed edges
    reconstructed_edges = [[]] * m

    # Initialize a heap for managing the vertices
    c = []
    for i in range(1, n - 1):
        c.append((i + 2, i))
    heapify(c)

    # Variable to keep track of the current vertex number
    j = 1

    for i in sorted_indices:
        if edges[i][1] == 1:
            # Edge is part of the MST
            reconstructed_edges[i] = [j, j + 1]
            j += 1
        else:
            # Edge is not part of the MST
            if not c:
                return -1
            z = heappop(c)
            if j < z[0]:
                return -1
            else:
                reconstructed_edges[i] = [z[1], z[0]]
                if z[0] + 1 <= n:
                    heappush(c, (z[0] + 1, z[1]))

    return reconstructed_edges

def calculate_max_damage(n, m, jiro_cards, ciel_cards):
    # Separate Jiro's cards into attack and defense lists
    a = [val for t, val in jiro_cards if t == 'ATK']
    d = [val for t, val in jiro_cards if t == 'DEF']

    # Sort Ciel's cards
    my = sorted(ciel_cards)

    # Sort Jiro's attack cards
    a.sort()

    # Sort Jiro's defense cards
    d.sort()

    def solve1():
        ret = 0
        used = [False] * m
        for val in d:
            for i in range(m):
                if not used[i] and my[i] > val:
                    used[i] = True
                    break
            else:
                return 0
        for val in a:
            for i in range(m):
                if not used[i] and my[i] >= val:
                    used[i] = True
                    ret += my[i] - val
                    break
            else:
                return 0
        return ret + sum([my[i] for i in range(m) if not used[i]])

    def solve2():
        ret = 0
        for k in range(min(len(a), m)):
            if my[-k - 1] >= a[k]:
                ret += my[-k - 1] - a[k]
            else:
                break
        return ret

    # Return the maximum damage from both strategies
    return max(solve1(), solve2())

