def calculate_minimum_resistors(a: int, b: int) -> int:
    def rec(a, b):
        ans = 0
        while True:
            if a == b:
                ans += 1
                break
            elif a == 0 or b == 0:
                break
            if a > b:
                k = (a - a % b) // b
                (a, b) = (a % b, b)
            elif a < b:
                k = (b - b % a) // a
                (a, b) = (a, b % a)
            ans += k
        return ans

    return rec(a, b)

def prefix_to_infix(pre_exp: str) -> str:
    stk = []
    i = len(pre_exp) - 1
    while i >= 0:
        if pre_exp[i] in ['+', '-', '*', '/', '^']:
            op1 = stk.pop()
            op2 = stk.pop()
            stk.append(f'({op1}{pre_exp[i]}{op2})')
        else:
            stk.append(pre_exp[i])
        i -= 1
    return stk.pop()

