        s2 = dict[i + 1]
        n = min(len(s1), len(s2))
        for j in range(n):
            if s1[j] != s2[j]:
                adj[ord(s1[j]) - ord('a')].append(ord(s2[j]) - ord('a'))
                break

    ind = [0] * K
    q = deque()
    for i in range(K):
        for it in adj[i]:
            ind[it] += 1

    for i in range(K):
        if ind[i] == 0:
            q.append(i)

    tpo = []
    while q:
        node = q.popleft()
        tpo.append(node)
        for child in adj[node]:
            ind[child] -= 1
            if ind[child] == 0:
                q.append(child)

    ans = ''
    for it in tpo:
        ans += chr(it + ord('a'))

    return ans

