def phiSum(N):
    def euler_totient(n):
        result = n
        p = 2
        while p * p <= n:
            if n % p == 0:
                while n % p == 0:
                    n //= p
                result -= result // p
            p += 1
        if n > 1:
            result -= result // n
        return result

    total_sum = 0
    for i in range(1, N + 1):
        if N % i == 0:
            total_sum += euler_totient(i)

    return total_sum

