    for i in range(n):
        if colors[i] == 'B':
            balance[i + 1] = -1
        else:
            balance[i + 1] = 1

    # Update the balance of each vertex based on its children
    for i in range(n - 1):
        balance[parents[n - (i + 2)]] += balance[n - i]

    # Count the number of balanced subtrees
    return list(balance.values()).count(0)

