def calculate_maximum_happiness(n, q, sizes, strings, queries):
    def b_s(take, left, right):
        (l, h) = (0, len(take) - 1)
        while l <= h:
            mid = (l + h) // 2
            if take[mid] < left:
                l = mid + 1
                continue
            if take[mid] > right:
                h = mid - 1
                continue
            return take[mid]
        return -1  # Return -1 if no valid index is found

    def sparse_query(b, left, right):
        dist = right - left + 1
        if dist == 0:
            return 0
        for i in range(19, -1, -1):
            if dist >> i & 1:
                msb = i
                break
        return max(b[left][msb], b[right - (1 << msb) + 1][msb])

    def sparse_table(b):
        for j in range(1, 20):
            for i in range(n - (1 << j - 1)):
                b[i][j] = max(b[i][j - 1], b[i + (1 << j - 1)][j - 1])

    best_ans = [[0 for i in range(20)] for j in range(n)]
    best_suf = [[0 for i in range(20)] for j in range(n)]
    best_pref = [[0 for i in range(20)] for j in range(n)]
    takes = dict()
    takep = dict()
    total = [0]

    for i in range(n):
        (ans, sval) = (0, 0)
        for j in strings[i]:
            if j == '1':
                sval += 1
            else:
                sval -= 1
            ans = max(ans, sval)
            if sval <= 0:
                sval = 0
        best_ans[i][0] = ans
        (ans, sval) = (0, 0)
        for j in strings[i]:
            if j == '1':
                sval += 1
            else:
                sval -= 1
            ans = max(ans, sval)
        best_pref[i][0] = ans - max(0, sval)
        total.append(total[-1] + max(0, sval))
        key = ans - max(0, sval)
        if key not in takep:
            takep[key] = []
        takep[key].append(i)
        (ans, sval) = (0, 0)
        for j in strings[i][::-1]:
            if j == '1':
                sval += 1
            else:
                sval -= 1
            ans = max(ans, sval)
        best_suf[i][0] = ans - max(0, sval)
        key = ans - max(0, sval)
        if key not in takes:
            takes[key] = []
        takes[key].append(i)

    sparse_table(best_pref)
    sparse_table(best_suf)
    sparse_table(best_ans)

    results = []
    for (l, r) in queries:
        (l, r) = (l - 1, r - 1)
        ans = sparse_query(best_ans, l, r)
        t = total[r + 1] - total[l]
        bs = sparse_query(best_suf, l, r)
        mid = b_s(takes[bs], l, r)
        if mid != -1:
            bp = max(sparse_query(best_pref, l, mid - 1), sparse_query(best_pref, mid + 1, r))
            ans = max(ans, t + bs + bp)
        bp = sparse_query(best_pref, l, r)
        mid = b_s(takep[bp], l, r)
        if mid != -1:
            bs = max(sparse_query(best_suf, l, mid - 1), sparse_query(best_suf, mid + 1, r))
            ans = max(ans, t + bp + bs)
        results.append(ans)

    return results

