    Parameters:
    arr (list): A list of integers.

    Returns:
    int: The maximum number of different values that can be achieved.
    """
    unique_values = set()
    for num in arr:
        if num in unique_values:
            unique_values.add(-num)
        else:
            unique_values.add(num)
    return len(unique_values)

