    corner_row = []
    for i in range(n):
        if '1' in contamination_levels[i]:
            corner_row.append(i)

    if len(corner_row) != 2:
        return early_exit()

    def check_zero(x):
        return all(i == '0' for i in x)

    for i in range(corner_row[0]):
        if not check_zero(contamination_levels[i]):
            return early_exit()

    for i in range(corner_row[1] + 1, n):
        if not check_zero(contamination_levels[i]):
            return early_exit()

    left_corner = None
    right_corner = None
    for j in range(n):
        if contamination_levels[corner_row[0]][j] != '0':
            left_corner = j
            break

    for j in range(n - 1, -1, -1):
        if contamination_levels[corner_row[0]][j] != '0':
            right_corner = j
            break

    if contamination_levels[corner_row[0]][left_corner] != '1' or contamination_levels[corner_row[0]][right_corner] != '1' or left_corner == right_corner:
        return early_exit()

    left2_corner = None
    right2_corner = None
    for j in range(n):
        if contamination_levels[corner_row[1]][j] != '0':
            left2_corner = j
            break

    for j in range(n - 1, -1, -1):
        if contamination_levels[corner_row[1]][j] != '0':
            right2_corner = j
            break

    if contamination_levels[corner_row[1]][left2_corner] != '1' or contamination_levels[corner_row[1]][right2_corner] != '1' or left_corner != left2_corner or right_corner != right2_corner:
        return early_exit()

    for i in corner_row:
        for j in range(left_corner + 1, right_corner):
            if contamination_levels[i][j] != '2':
                return early_exit()

    for i in range(corner_row[0] + 1, corner_row[1]):
        if not check_zero(contamination_levels[i][:left_corner]):
            return early_exit()
        if not check_zero(contamination_levels[i][right_corner + 1:]):
            return early_exit()
        if contamination_levels[i][left_corner] != '2' or contamination_levels[i][right_corner] != '2':
            return early_exit()
        for j in range(left_corner + 1, right_corner):
            if contamination_levels[i][j] != '4':
                return early_exit()

    return True

