        B = []
        z = 2
        while z * z <= c:
            if c % z == 0 and 1 < c // z <= y:
                B.append(c // z)
                B.append(z)
                c = 1
                break
            z += 1
        while z >= 2 and c > 1:
            if c % z == 0 and 1 < z <= y:
                while c % z == 0 and c > y:
                    B.append(z)
                    c //= z
            if 1 < c <= y:
                B.append(c)
                c = 1
                break
            z -= 1
        if c > 1:
            return None
        return sorted(B)

    def solve(c, x, n):
        y = x
        A = []
        while c % y == 0:
            c //= y
            A.append(y)
            B = calc(c, y)
            if B is not None:
                X = sorted(B) + A[::-1]
                m = len(X)
                if m <= n:
                    res = [1] * (n - m) + X
                    return [e + i for (i, e) in enumerate(res)]
            y += 1
        return None

    x = 1
    ans = None
    while x * x <= C:
        if C % x == 0:
            res = solve(C, x, N)
            if res is not None:
                ans = res
                break
        x += 1
    else:
        while x >= 1:
            if C % x == 0:
                res = solve(C, C // x, N)
                if res is not None:
                    ans = res
                    break
            x -= 1
    return ans

import math

def prime_sum(N):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    sum_of_primes = 0
    while N > 0:
        digit = N % 10
        if is_prime(digit):
            sum_of_primes += digit
        N = N // 10

    return sum_of_primes

