def calculate_remainder(n: int, a: int, b: int, k: int, s: str) -> int:
    mod = 1000000009
    ans = 0
    t = (n + 1) // k

    def modInverse(a):
        return pow(a, mod - 2, mod)

    i = 0
    for ind in range(len(s)):
        first = pow(a, n - i, mod) * pow(b, i, mod) % mod
        num = pow(b, k, mod) * modInverse(pow(a, k, mod)) % mod
        if b >= a:
            den = (num - 1 + mod) % mod
            num = (pow(num, t, mod) - 1 + mod) % mod
        else:
            den = (1 - num + mod) % mod
            num = (1 - pow(num, t, mod) + mod) % mod
        if num == 0:
            temp = t * first % mod
        else:
            temp = num * modInverse(den) % mod
            temp = temp * first % mod
        if s[ind] == '+':
            ans = (ans + temp) % mod
        elif s[ind] == '-':
            ans = (ans - temp + mod) % mod
        i += 1
        if i > n:
            i = 0
    return ans

def min_squares(L: int, B: int) -> int:
    p = 1000000007

    if L == 1:
        return B % p
    if B == 1:
        return L % p

    ans = 0
    while L > 0 and B > 0:
        if L > B:
            ans = (ans + L // B) % p
            L = L % B
        else:
            ans = (ans + B // L) % p
            B = B % L

    return ans % p

