def determine_divisibility_rule_type(b, d):
    # Check for 2-type rule
    for i in range(1, 10):
        if (b ** i) % d == 0:
            return "2-type", i

    # Check for 3-type rule
    if (b - 1) % d == 0:
        return "3-type", None

    # Check for 11-type rule
    if (b + 1) % d == 0:
        return "11-type", None

    # Check for 6-type rule
    for i in range(2, d + 1):
        if d % i == 0:
            x = 1
            while d % i == 0:
                d //= i
                x *= i
            if (b ** 10) % x != 0 and (b + 1) % x != 0 and (b - 1) % x != 0:
                return "7-type", None

    return "6-type", None

