def min_operations_to_equal_mean_median(arr, n):
    def check(arr, mean, n):
        sum_arr = sum(arr)
        allowed_operations = n * mean - sum_arr
        if allowed_operations < 0:
            return -1
        required_operations = 0
        for i in range((n - 1) // 2, n):
            required_operations += max(0, mean - arr[i])
        if required_operations > allowed_operations:
            return -1
        else:
            return allowed_operations

    arr = sorted(arr)
    l = arr[(n - 1) // 2]
    r = arr[n - 1]
    ans = -1

    while l <= r:
        mid = (l + r) // 2
        minOp = check(arr, mid, n)
        if minOp != -1:
            ans = minOp
            r = mid - 1
        else:
            l = mid + 1

    return ans

def determine_game_winner(N, M, edges):
    class UnionFindVerSize:
        def __init__(self, N):
            self._parent = [n for n in range(0, N)]
            self._size = [1] * N
            self.group = N

        def find_root(self, x):
            if self._parent[x] == x:
                return x
            self._parent[x] = self.find_root(self._parent[x])
            stack = [x]
            while self._parent[stack[-1]] != stack[-1]:
                stack.append(self._parent[stack[-1]])
            for v in stack:
                self._parent[v] = stack[-1]
            return self._parent[x]

        def unite(self, x, y):
            gx = self.find_root(x)
            gy = self.find_root(y)
            if gx == gy:
                return
            self.group -= 1
            if self._size[gx] < self._size[gy]:
                self._parent[gx] = gy
                self._size[gy] += self._size[gx]
            else:
                self._parent[gy] = gx
                self._size[gx] += self._size[gy]

        def get_size(self, x):
            return self._size[self.find_root(x)]

        def is_same_group(self, x, y):
            return self.find_root(x) == self.find_root(y)

    uf = UnionFindVerSize(N)
    for a, b in edges:
        uf.unite(a - 1, b - 1)

    if N % 2 == 1:
        all_possible_edges = N * (N - 1) // 2 - M
        if all_possible_edges % 2 == 0:
            return 'Second'
        else:
            return 'First'
    else:
        all_possible_edges = N * (N - 1) // 2 - M
        s1 = uf.get_size(0)
        sN = uf.get_size(N - 1)
        if s1 % 2 == sN % 2:
            if s1 % 2 == 0:
                if all_possible_edges % 2 == 0:
                    return 'Second'
                else:
                    return 'First'
            elif all_possible_edges % 2 == 1:
                return 'Second'
            else:
                return 'First'
        else:
            return 'First'

