modul = 998244353

def modiFun(a, b, p):
    a %= p
    b %= p
    if b == 1:
        return 0
    (count, t, g) = (0, 1, gcd(a, p))
    while g != 1:
        if b % g:
            return -1
        p = p // g
        b = b // g
        t = int(int(int(t * a) // g) % p)
        count += 1
        if b == t:
            return count
        g = gcd(a, p)
    (hash, base, m) = ({}, b, int(sqrt(1.0 * p) + 1))
    for i in range(m):
        hash[base] = i
        base = base * a % p
    (base, temp) = (pow(a, m, p), t)
    for i in range(1, m + 2):
        temp = temp * base % p
        if temp in hash.keys():
            return i * m - hash[temp] + count
    return -1

def find_smallest_beauty(n, x, m):
    if 1 % m == x:
        return 0
    if x == 0 and m == 1:
        return 0
    if x == 0 and n != 1:
        return 1

    var = (pow(2, n, m) - 1 + m) % m
    power = modiFun(var, x, m)

    if power == -1:
        return -1

    answ = pow(2, n - 1, modul) * (pow(2, power, modul) - 1 + modul) % modul % modul

    if answ == 0:
        if 1 % m != x:
            answ = -1
    if answ == 1:
        if 1 % m != x or n != -1:
            answ -= 1

    return answ

