            if x < N - 1 and not visited1[x + 1]:
                q1.append(x + 1)
                visited1[x + 1] = True
        t += 1

    result = ''
    for i in range(N):
        if S[i] == '1':
            if nrstzeroes[i] % 2 != K % 2 and K > nrstzeroes[i]:
                result += '1'
            else:
                result += '0'
        elif nrstones[i] % 2 == K % 2 and K >= nrstones[i]:
            result += '1'
        else:
            result += '0'

    return result

