def calculate_total_candies(T, test_cases):
    def ctlt(arr, val):
        if arr[0] >= val:
            return 0
        lo = 0
        hi = len(arr)
        while hi - lo > 1:
            md = (hi + lo) // 2
            if arr[md] < val:
                lo = md
            else:
                hi = md
        return hi

    results = []

    for case in test_cases:
        (n, k, x, d, ps) = case
        ps.sort()

        if x < n or x < ps[-1] or n < k:
            results.append(-1)
            continue

        valchecked = 0
        fillval = 0
        valsdone = False
        isolbelow = True
        lastp = ps[0]

        while not valsdone and n >= k:
            if n == k:
                lo = x + d + 1
            else:
                lo = 1
                hi = x + 1
                while hi - lo > 1:
                    md = (hi + lo) // 2
                    v = x - md + 1 + ctlt(ps, md)
                    if v < n:
                        hi = md
                    else:
                        lo = md

            valsdone = True
            checkto = ctlt(ps, lo) - 1

            if checkto >= valchecked:
                for p in ps[valchecked + 1:checkto + 1]:
                    if lastp + d >= p:
                        isolbelow = False
                    elif isolbelow:
                        valsdone = False
                        fillval += lastp + d
                        n -= 1
                        isolbelow = p > lastp + 2 * d
                    else:
                        isolbelow = True
                    lastp = p

                valchecked = checkto

                if valsdone and isolbelow:
                    if lastp + d >= lo:
                        isolbelow = False
                    else:
                        valsdone = False
                        fillval += lastp
                        ps[checkto] += d
                        lastp += d
                        isolbelow = False
                        n -= 1

        if k > n:
            results.append(-1)
        elif k == n:
            results.append(sum(ps) + fillval)
        elif k == n - 1 and lo > ps[-1]:
            results.append(sum(ps) + fillval + min(x, ps[-1] + d))
        else:
            tot = (x + lo) * (x - lo + 1) // 2 + sum(ps[:ctlt(ps, lo)])
            results.append(tot + fillval)

    return results

