def can_permute_for_multiple_of_4(N, a):
    """
    Determines if Snuke can permute the elements in the sequence `a` such that
    for each 1 ≤ i ≤ N - 1, the product of a_i and a_{i + 1} is a multiple of 4.

    Parameters:
    - N (int): The length of the sequence.
    - a (list of int): The sequence of positive integers.

    Returns:
    - bool: True if Snuke can achieve his objective, False otherwise.
    """
    b1, b2, b4 = 0, 0, 0

    for i in a:
        if i % 2 != 0:
            b1 += 1
        elif i % 4 == 0:
            b4 += 1
        else:
            b2 += 1

    if b1 <= b4:
        return True
    elif b1 <= b4 + 1 and not b2:
        return True
    else:
        return False

def count_ways_to_express_as_sum_of_powers(n: int, x: int) -> int:
    M = 1000000007
    powers = []
    i = 1
    while True:
        power = pow(i, x)
        if power <= n:
            powers.append(power)
            i += 1
        else:
            break

    dp = [0] * (n + 1)
    dp[0] = 1

    for power in powers:
        for i in range(n, -1, -1):
            if i - power >= 0:
                dp[i] = (dp[i - power] + dp[i]) % M

    return dp[n]

