def minimum_cost(cost, N, W):
    def go(ind, currw):
        if currw > W:
            return 10 ** 18
        if ind == N:
            if currw == W:
                return 0
            return 10 ** 18
        if dp[ind][currw] != -1:
            return dp[ind][currw]
        c1 = 10 ** 18
        if cost[ind] != -1:
            c1 = cost[ind] + go(ind, currw + ind + 1)
        c2 = go(ind + 1, currw)
        ans = min(c1, c2)
        dp[ind][currw] = ans
        return ans

