    for i in range(n):
        if i == 0 or genres[i] != genres[i - 1]:
            distinct_genres.append(genres[i])

    # Calculate the stresses for each genre
    for i in range(len(distinct_genres)):
        if 0 < i < len(distinct_genres) - 1 and distinct_genres[i - 1] == distinct_genres[i + 1]:
            ans[distinct_genres[i]] += 2
        else:
            ans[distinct_genres[i]] += 1

