    rangeData = {}

    primes[K] = distinctPrimeFactors(K)
    results = []

    for query in queries:
        if query[0] == '!':
            (cmd, l, r, x) = query.split()
            l = int(l)
            r = int(r)
            x = int(x)
            start = l
            end = r
            startflag = False
            for i in sorted(rangeData):
                rangeVal = i
                if start > rangeVal[1]:
                    continue
                if end < rangeVal[0]:
                    break
                startRange = start
                endRange = end
                if start >= rangeVal[0] and start <= rangeVal[1]:
                    start = rangeVal[1] + 1
                    continue
                if end >= rangeVal[0]:
                    endRange = rangeVal[0] - 1
                if startRange <= endRange:
                    rangeData[startRange, endRange] = x
                    start = max(endRange + 1, rangeVal[1] + 1)
            if start <= end:
                rangeData[start, end] = x
        elif query[0] == '?':
            (cmd, l, r) = query.split()
            l = int(l)
