def min_absolute_difference_modulo(n, p, k_list):
    MOD = 10 ** 9 + 7

    if p == 1:
        return len(k_list) % 2

    k_list.sort(reverse=True)
    left = Counter()
    right = Counter()

    for k in k_list:
        if not left:
            left[k] += 1
        else:
            if k in left:
                del left[k]
                continue
            right[k] += 1
            while True:
                (q, r) = divmod(right[k], p)
                right[k] = r
                right[k + 1] += q
                if q == 0:
                    break
                if k + 1 in left:
                    assert right[k + 1] == 1
                    del left[k + 1]
                    del right[k + 1]
                    break
                k += 1

    right_sum = sum((v * pow(p, k, MOD) for (k, v) in right.items())) % MOD

    if not left:
        return right_sum

    left_sum = sum((v * pow(p, k, MOD) for (k, v) in left.items())) % MOD

    return (left_sum - right_sum) % MOD

