        prob.append(prob[-1] + (-1) ** c * inverse(power(2, c)))
        prob[-1] %= MOD

    res = 0

    # Process rows
    for r in range(n):
        cnt = 0
        for c in range(m):
            if grid[r][c] == 'o':
                cnt += 1
            else:
                cnt = 0
            res += prob[cnt]
            res %= MOD

    # Process columns
    for c in range(m):
        cnt = 0
        for r in range(n):
            if grid[r][c] == 'o':
                cnt += 1
            else:
                cnt = 0
            res += prob[cnt]
            res %= MOD

