        elif len(pl) >= 3 and len(nl) >= 2 or (len(pl) >= 1 and len(nl) >= 4) or len(pl) == 5:
            ans1 = ans2 = ans3 = 1
            if len(pl) == 5:
                ans1 = reduce(lambda x, y: x * y, pl)
            if len(pl) >= 3:
                pp = 1
                for i in range(3):
                    pp = pp * pl[i]
                np = nl[0] * nl[1]
                ans2 = pp * np
            if len(nl) == 4:
                ans3 = reduce(lambda x, y: x * y, nl)
                ans3 = ans3 * pl[0]
            ans = max(ans1, ans2, ans3)
        else:
            ans = 0

        results.append(ans)

    return results

def find_first_empty_room(rooms):
    try:
        return rooms.index('O')
    except ValueError:
        return 'None available!'

def count_factors(N: int) -> int:
    count = 0
    for i in range(1, int(N ** 0.5) + 1):
        if N % i == 0:
            count += 1
            if i != N // i:
                count += 1
    return count

def equalize_chocolates(arr):
    def steps(number):
        remainder = [0, 1, 1, 2, 2]
        return number // 5 + remainder[number % 5]

    if not arr:
        return 0

    arr.sort()
    minimum = arr[0]
    totalsteps = [0, 1, 1, 2, 2]

    for i in range(5):
        for element in arr[1:]:
            totalsteps[i] += steps(element - minimum + i)

    return min(totalsteps)

def can_make_equal(A, B, X):
    if (A - B) % (2 * X) == 0:
        return 'YES'
    else:
        return 'NO'

def minimize_total_coins(P, N):
    price = [1, 5, 10, 50, 100, 500]
    ans = float('inf')

    p_sum = sum(map(lambda s: s[0] * s[1], zip(price, N)))

    for change in range(1000):
        total = P + change
        pay = [0] * 6

        for i in reversed(range(6)):
            if total >= price[i]:
                pay[i] = min(N[i], int(total / price[i]))
                total -= pay[i] * price[i]

        if total > 0:
            break

        coins = sum(pay)
        _change = change

        for i in reversed(range(6)):
            if _change >= price[i]:
                coins += int(_change / price[i])
                _change %= price[i]

        ans = min(ans, coins)

    return ans
